\label{prop:x0-det} For any rooted graph $G_*$,
\begin{equation}\label{eq:x0-det}
  X_0(G_*)=\frac{\sum_{i=0}^N (0,i)\bullet X_{\neq 0}(G_*)}{N}-X_{\neq 0}(G_*).
\end{equation}

\label{prop:recT}
Let $T_*$ be a rooted tree with principal rooted subtrees
$T_{1*},T_{2*},\ldots,T_{c*}$. Then
\begin{equation}\label{eq:recT}
 X_0(T_*)=x_0\prod_{j=1}^c X_{\neq 0}(T_{j*}). 
\end{equation}

\label{prop:x0-det2}
For any rooted graph $G_*$ with $n$ vertices:
\ (a) $f_0(G_*)=f_1(G_*)$ and $f_2(G_*)=f_3(G_*)=\operatorname{rev}_n(f_0(G_*))$.
\ (b) $f_{
eq 0}(G_*)=f_{
eq 1}(G_*)$ and
       $f_{
eq 2}(G_*)=f_{
eq 3}(G_*)=\operatorname{rev}_n(f_{
eq 0}(G_*))$.
\ (c) $f_G=2f_0(G_*)+2\operatorname{rev}_n(f_0(G_*))$.
\ (d) $f_G=(2/3)f_{
eq 0}(G_*)+(2/3)\operatorname{rev}_n(f_{
eq 0}(G_*))$.
\ (e) $f_0(G_*)=f_G-f_{
eq 0}(G_*)
     =(-1/3)f_{
eq 0}(G_*)+(2/3)\operatorname{rev}_n(f_{
eq 0}(G_*))$.

\label{thm:best}
For all rooted trees $T_*$ and $U_*$ and all $N\geq 3$,
the following conditions are equivalent:
(a)~$T_*\cong U_*$; 
(b)~$X_0(T_*;x_0,\ldots,x_N)=X_0(U_*;x_0,\ldots,x_N)$;
(c)~$f_0(T_*)=f_0(U_*)$.

\label{ex:path3b}
Continuing Example~\ref{ex:path3a}, we use Theorem~\ref{thm:dc} to compute
(for $N=2$)
\begin{align*}
  X_0(\raisebox{-0.1\height}{\includegraphics[width=1cm]{ex-A}}) &=
  X_0(\raisebox{-0.1\height}{\includegraphics[width=1cm]{ex-dc1}})-x_0X_0(\raisebox{-0.1\height}{\includegraphics[width=0.6cm]{ex-dc2}}) 
= x_0(2x_0x_1 + 2x_0x_2 + 2x_1x_2) - x_0(x_0x_1 + x_0x_2)
\\ &= 2x_0x_1x_2 + x_0^2x_1 + x_0^2x_2,
\end{align*}
in agreement with~\eqref{eq:exA}.

For all trees $T$ and $U$ with at most $N+1$ vertices,
\begin{equation*}
  T\cong U \text{ if and only if } 
  X_T(1,q,q^2,\ldots,q^N)=X_U(1,q,q^2,\ldots,q^N).
\end{equation*}

Stanley~\cite[pg. 170]{stanley} gave this example of two non-isomorphic graphs
with equal chromatic symmetric functions:
\begin{equation*}
    X_{\raisebox{-0.4\height}{\includegraphics[width=0.8cm]{stan-A}}} =
    X_{\raisebox{-0.4\height}{\includegraphics[width=1.1cm]{stan-B}}} =
    2\widetilde{m}_{221} + 4\widetilde{m}_{2111} + \widetilde{m}_{11111}.
\end{equation*}
Let $z=x_0$.  For the first graph $G$, the multiset $[X_0(G_*^r)]$ consists of
 \begin{align*}
    X_0\left(\raisebox{-0.4\height}{\includegraphics[width=0.8cm]{stan-A-1}}
\right) =
    X_0\left(\raisebox{-0.4\height}{\includegraphics[width=0.8cm]{stan-A-3}}
\right) =
    X_0\left(\raisebox{-0.4\height}{\includegraphics[width=0.8cm]{stan-A-4}}
\right) =
    X_0\left(\raisebox{-0.4\height}{\includegraphics[width=0.8cm]{stan-A-5}}
\right) &=
    z(2\widetilde{m}_{211} + \widetilde{m}_{1111}) + z^2(2\widetilde{m}_{21} + 2\widetilde{m}_{111}),\\
    X_0\left(\raisebox{-0.4\height}{\includegraphics[width=0.8cm]{stan-A-2}}
\right) &=
    z(2\widetilde{m}_{22} + 4\widetilde{m}_{211} + \widetilde{m}_{1111}).
  \end{align*}
For the second graph $H$, the multiset $[X_0(H_*^s)]$ consists of
  \begin{align*}
    X_0\left(\raisebox{-0.4\height}{\includegraphics[width=1.1cm]{stan-B-1}}
\right) =
    X_0\left(\raisebox{-0.4\height}{\includegraphics[width=1.1cm]{stan-B-5}}
\right) &=
    z(\widetilde{m}_{22} + 3\widetilde{m}_{211} + \widetilde{m}_{1111}) + z^2(\widetilde{m}_{21} + \widetilde{m}_{111}),\\
    X_0\left(\raisebox{-0.4\height}{\includegraphics[width=1.1cm]{stan-B-2}}
\right) &=
    z(2\widetilde{m}_{211} + \widetilde{m}_{1111}) + z^2(2\widetilde{m}_{21} + 2\widetilde{m}_{111}),\\
    X_0\left(\raisebox{-0.4\height}{\includegraphics[width=1.1cm]{stan-B-3}}
\right) &=
    z(3\widetilde{m}_{211} + \widetilde{m}_{1111}) + z^2(2\widetilde{m}_{21} + \widetilde{m}_{111}),\\
    X_0\left(\raisebox{-0.4\height}{\includegraphics[width=1.1cm]{stan-B-4}}
\right) &=
    z(\widetilde{m}_{211} + \widetilde{m}_{1111}) + z^2(2\widetilde{m}_{21} + 3\widetilde{m}_{111}).\\
\end{align*}
This calculation also shows that there exist non-isomorphic rooted graphs
$G_*$ and $H_*$ with $X_0(G_*)=X_0(H_*)$. Indeed, we may take
\[ G_*= \raisebox{-0.4\height}{\includegraphics[width=0.8cm]{stan-A-1}}
\quad\mbox{ and }\quad
   H_*= \raisebox{-0.4\height}{\includegraphics[width=1.1cm]{stan-B-2}}.  \]

\label{prop:pointing} For any graph $G$, 
\begin{equation}\label{eq:pointing}
x_0\frac{\partial}{\partial x_0} X_G(x_0,\ldots,x_N)
 = \sum_{r\in V(G)} X_0(G_*^r;x_0,\ldots,x_N).
\end{equation}

\label{ex:path3c}
Continuing Example~\ref{ex:path3a}, the following
calculation illustrates Proposition~\ref{prop:pointing}:
\begin{align*}
  X_0(\raisebox{-0.1\height}{\includegraphics[width=1cm]{ex-A}}) &+ X_0(\raisebox{-0.1\height}{\includegraphics[width=1cm]{ex-B}}) + X_0(\raisebox{-0.1\height}{\includegraphics[width=1cm]{ex-C}}) \\
  &= (2x_0x_1x_2 + x_0^2(x_1+x_2)) 
+ (2x_0x_1x_2 + x_0(x_1^2 + x_2^2)) + (2x_0x_1x_2 + x_0^2(x_1+x_2))\\
  &= 6x_0x_1x_2 + 2x_0^2(x_1+x_2) + x_0(x_1^2 + x_2^2) = x_0\frac{\partial}{\partial x_0} X_{\includegraphics[width=1cm]{ex}}(x_0,x_1,x_2).
\end{align*}

\label{prop:p-exp}
For all rooted graphs $G_*^v$ and $N\geq |V(G)|$,
\begin{equation}\label{eq:p-exp}
 X_0(G_*^v;x_0,x_1,\ldots,x_N)
 =\sum_{S\subseteq E(G)} (-1)^{|S|}
  p_{\lambda_v^-(G_S)}(x_0,x_1,\ldots,x_N)x_0^{\lambda_v^+(G_S)}.
\end{equation}

\label{ex:pointed2} For 
$G_*^v=\raisebox{-0.1\height}{\includegraphics[width=1.5cm]{pointed-graph-B}}$, 
  we use Equation~\eqref{eq:pointed-def} to compute
  \begin{equation}\label{eq:pointed-ex-2}
    P_{G,v} = (p_{1111} - 2p_{211} + p_{31})z^0 +
    (-2p_{111}+2p_{21}-p_3)z^1 + (3p_{11})z^2 + (-3p_1)z^3 + z^4.
  \end{equation}
Replacing each $p_k$ by $z^k+p_k$ and simplifying, we obtain
  \begin{equation}
  X_0(G_*^v) = (p_{1111}-2p_{211}+p_{31})z + (2p_{111}-2p_{21})z^2 + p_{11}z^3.
  \end{equation}
  Notice that the coefficient of $z=x_0$ in $X_0(G_*^v)$ and $zP_{G,v}$
  is the same; this holds in general.

\label{lem:subtree-var}
For any connected graph $H$ with $k+1$ vertices,
$f(H)$ is the number of internal spanning trees of $H$.
